70	    public async Task<LatestLessonsResponse> GetLatestLessonsAsync(int limit, CancellationToken ct = default)
71	    {
72	        var safeLimit = Math.Clamp(limit, 1, 20);
73	
74	        var latestResults = await db.AiResults
75	            .AsNoTracking()
76	            .Where(r => r.IsScreenshotGenerated)
77	            .OrderByDescending(r => r.GeneratedAt.HasValue)
78	            .ThenByDescending(r => r.GeneratedAt)
79	            .ThenByDescending(r => r.CreatedAt)
80	            .Take(safeLimit)
81	            .Select(r => new
82	            {
83	                r.LessonId,
84	                r.CourseKey,
85	                r.CourseId,
86	                r.ClassSection,
87	                r.LessonDate,
88	                r.GeneratedAt,
89	                r.CreatedAt
90	            })
91	            .ToListAsync(ct);
92	
93	        if (latestResults.Count == 0)
94	            return new LatestLessonsResponse([]);
95	
96	        var courseKeys = latestResults.Select(r => r.CourseKey).Distinct().ToList();
97	        var courses = await db.Courses
98	            .AsNoTracking()
99	            .Where(c => courseKeys.Contains(c.CourseKey))
100	            .Select(c => new { c.CourseKey, c.Name, c.Section, c.SchedulesJson })
101	            .ToDictionaryAsync(c => c.CourseKey, ct);
102	
103	        var lessons = latestResults.Select(result =>
104	        {
105	            courses.TryGetValue(result.CourseKey, out var course);
106	
107	            return new LatestLessonDto(
108	                LessonId: result.LessonId,
109	                CourseKey: result.CourseKey,
110	                CourseName: course?.Name ?? "",
111	                CourseId: result.CourseId,
112	                CourseSection: result.ClassSection,
113	                CourseSchedule: course?.SchedulesJson is null
114	                    ? []
115	                    : JsonSerializer.Deserialize<List<CourseScheduleDto>>(course.SchedulesJson, _caseInsensitive) ?? [],
116	                LessonDate: result.LessonDate?.ToString("yyyy-MM-dd"),
117	                GeneratedAt: result.GeneratedAt?.ToString("o"),
118	                CreatedAt: result.CreatedAt.ToString("o")
119	            );
120	        }).ToList();
121	
122	        return new LatestLessonsResponse(lessons);
123	    }
