125	    private async Task<LessonResultDto?> BuildResultFromDbAsync(string lessonId, CancellationToken ct)
126	    {
127	        var windows = await db.AiWindows
128	            .AsNoTracking()
129	            .Where(w => w.LessonId == lessonId)
130	            .OrderBy(w => w.WindowIndex)
131	            .ToListAsync(ct);
132	
133	        if (windows.Count == 0) return null;
134	
135	        var seats = await db.AiWindowSeats
136	            .AsNoTracking()
137	            .Where(s => s.LessonId == lessonId)
138	            .ToListAsync(ct);
139	
140	        // group seats by (WindowIndex, SeatKey) for fast lookup
141	        var seatsByWindow = seats
142	            .GroupBy(s => s.WindowIndex)
143	            .ToDictionary(
144	                g => g.Key,
145	                g => g.GroupBy(s => s.SeatKey)
146	                      .ToDictionary(
147	                          sg => sg.Key,
148	                          sg => sg.ToDictionary(s => s.EngagementLevel, s => s.Value)
149	                      )
150	            );
151	
152	        var classSlices = new List<EngagementSliceDto>();
153	        var groupSlices = new Dictionary<string, List<EngagementSliceDto>>();
154	
155	        foreach (var win in windows)
156	        {
157	            if (!seatsByWindow.TryGetValue(win.WindowIndex, out var winSeats)) continue;
158	
159	            var byGroup = winSeats
160	                .GroupBy(kvp => kvp.Key.Contains('_') ? kvp.Key[..kvp.Key.IndexOf('_')] : kvp.Key)
161	                .ToDictionary(g => g.Key, g => g.Select(kvp => kvp.Value).ToList());
162	
163	            // class average: average across all seats in this window
164	            var allSeatLevels = winSeats.Values.ToList();
165	            classSlices.Add(new EngagementSliceDto(win.WindowIndex, AverageEngagements(allSeatLevels)));
166	
167	            // group (table) averages
168	            foreach (var (groupKey, seatLevels) in byGroup)
169	            {
170	                if (!groupSlices.ContainsKey(groupKey))
171	                    groupSlices[groupKey] = [];
172	                groupSlices[groupKey].Add(new EngagementSliceDto(win.WindowIndex, AverageEngagements(seatLevels)));
173	            }
174	        }
175	
176	        return new LessonResultDto(groupSlices, classSlices);
177	    }
178	
179	    private static List<int> AverageEngagements(List<Dictionary<string, double>> seats)
180	    {
181	        var sum = new double[4];
182	        foreach (var seat in seats)
183	            for (var level = 0; level < 4; level++)
184	                sum[level] += seat.GetValueOrDefault(level.ToString());
185	        return FractionsToPercentages(sum.Select(v => v / seats.Count));
186	    }
187	
188	    private static List<int> FractionsToPercentages(IEnumerable<double> fractions)
189	    {
190	        var pcts = fractions.Select(f => (int)Math.Round(f * 100)).ToList();
191	        var diff = 100 - pcts.Sum();
192	        if (diff != 0 && pcts.Count > 0) pcts[^1] = Math.Max(0, pcts[^1] + diff);
193	        return pcts;
194	    }
